import { useState } from "react"
import { createRoot } from "react-dom/client"

function OrderForm() {
  const [name, setName] = useState("")
  const [phone, setPhone] = useState("")
  const [mode, setMode] = useState("pickup")
  const [address, setAddress] = useState("")
  const [notes, setNotes] = useState("")
  const [sent, setSent] = useState(false)

  const phoneOk = /^0\d{10}$/.test(phone)
  const canSend = name.trim() !== "" && phoneOk

  function handleSubmit(e) {
    e.preventDefault()
    if (canSend) setSent(true)
  }

  if (sent) return <p className="thanks">Thanks, {name}! We'll call {phone}.</p>

  return (
    <form onSubmit={handleSubmit}>
      <input id="name" placeholder="Your name" value={name} onChange={(e) => setName(e.target.value)} />
      <input id="phone" placeholder="0803…" value={phone} onChange={(e) => setPhone(e.target.value)} />
      {phone && !phoneOk && <p className="error">Use 11 digits starting with 0</p>}
      <select id="mode" value={mode} onChange={(e) => setMode(e.target.value)}>
        <option value="pickup">Pickup</option>
        <option value="delivery">Delivery</option>
      </select>
      {mode === "delivery" && <input id="address" placeholder="Delivery address" value={address} onChange={(e) => setAddress(e.target.value)} />}
      <textarea id="notes" placeholder="Notes for the kitchen" value={notes} onChange={(e) => setNotes(e.target.value)} />
      <p className="chars">{notes.length}/200</p>
      <button disabled={!canSend}>Send</button>
    </form>
  )
}

createRoot(document.getElementById("root")).render(<OrderForm />)
